/// <summary>
/// The <c>METApplicationInsightsEventProperties</c> class contains all available event properties that can be used in the Application Insights telemetry.
/// CB718 VM Task - 162235 Std code from Microsoft for logging
/// </summary>
/// <remarks>
/// The names must be unique.
/// Please keep the list sorted alphabetically in ascending order.
/// </remarks>
internal static final class METApplicationInsightsEventProperties
{
    internal static const str ElapsedMilliseconds   = 'ElapsedMilliseconds';
    internal static const str DefinitionGroup       = 'DefinitionGroup';
    internal static const str Entity                = 'Entity';
    internal static const str ExecutionId           = 'ExecutionId';
    internal static const str NoOfRecords           = 'NoOfRecords';
    internal static const str NumOfTargetNew        = 'NumOfTargetNew';
    internal static const str NumOfTargetUpdated    = 'NumOfTargetUpdated';
    internal static const str JournalId             = 'JournalId';
    internal static const str METCash               = 'METCash';
    internal static const str DMFError              = 'DMFError';
    internal static const str METReference          = 'METReference';
    internal static const str METDMFError           = 'MET DMF Error';
    internal static const str METJourError          = 'MET Journal Error';
    internal static const str ExceptionMessage      = 'ExceptionMessage';
    internal static const str CallStack             = 'CallStack';
    internal static const str LegalEntity           = 'LegalEntity';
    internal static const str StartDateTime         = 'StartDateTime';
    internal static const str BatchJobName          = 'BatchJobName';
    internal static const str BatchJobId            = 'BatchJobId';
    internal static const str BatchJobTaskId        = 'BatchJobTaskId';
    internal static const str DMFProjectDefinition  = 'DMFProjectDefinition';
    internal static const str DMFEntityName         = 'DMFEntityName';
    internal static const str DMFExecutionID        = 'DMFExecutionID';
    internal static const str DMFStagingErrorCount  = 'DMFStagingErrorCount';
    internal static const str DMFStagingStatus      = 'DMFStagingStatus';
    internal static const str DMFTargetErrorCount   = 'DMFTargetErrorCount';
    internal static const str DMFTargetStatus       = 'DMFTargetStatus';
}
